'use strict';
const express=require('express'),fs=require('fs'),path=require('path'),crypto=require('crypto'),{db}=require('../db'),{DATA_DIR,APP_DIR}=require('../paths'),{museWorker}=require('../museWorker'),{run}=require('../filmMedia.cjs');const router=express.Router(),active=new Map();
db.exec('CREATE TABLE IF NOT EXISTS muse_brief_sessions(id TEXT PRIMARY KEY,payload TEXT NOT NULL,updated_at TEXT NOT NULL)');
const save=p=>{p.updatedAt=new Date().toISOString();db.prepare('INSERT OR REPLACE INTO muse_brief_sessions VALUES(?,?,?)').run(p.id,JSON.stringify(p),p.updatedAt);return p},read=id=>{const row=db.prepare('SELECT payload FROM muse_brief_sessions WHERE id=?').get(id);if(!row)throw Error('Không tìm thấy brief.');return JSON.parse(row.payload)};
const ffmpeg=()=>require(path.join(APP_DIR,'vendor/media/node_modules/ffmpeg-static')).replace(/app\.asar([/\\])/,'app.asar.unpacked$1');
async function download(page,src,p,turn){const b64=await page.evaluate(async src=>{const u=new URL(src,location.href);if(!['https:','blob:'].includes(u.protocol))throw Error('Nguồn video không hợp lệ');const r=await fetch(u.href,{credentials:'include'});if(!r.ok)throw Error('Không tải được video');const b=new Uint8Array(await r.arrayBuffer());if(b.length>350*1024*1024)throw Error('Video vượt 350MB');let s='';for(let i=0;i<b.length;i+=32768)s+=String.fromCharCode(...b.subarray(i,i+32768));return btoa(s)},src);const name='brief_'+crypto.randomUUID()+'.mp4',file=path.join(DATA_DIR,'videos',name);fs.writeFileSync(file,Buffer.from(b64,'base64'));try{const info=await run(ffmpeg(),['-hide_banner','-i',file],{probe:true});const match=info.match(/Duration: (\d+):(\d+):([\d.]+)/);if(!match||!/Video:/.test(info))throw Error('File chưa xác nhận được video hợp lệ.');const duration=Number(match[1])*3600+Number(match[2])*60+Number(match[3]);return {url:'/videos/'+name,duration,turn,createdAt:new Date().toISOString()}}catch(e){fs.rmSync(file,{force:true});throw e}}
async function monitor(id,resume=false){if(active.has(id))return;const ctrl={stop:false,page:null};active.set(id,ctrl);let p=read(id);museWorker.lockedProfiles.add(p.accountId);try{const browser=await museWorker.getBrowser(p.accountId),page=await browser.newPage();ctrl.page=page;await page.goto(p.url||'https://muse.ai',{waitUntil:'domcontentloaded',timeout:60000});await museWorker.waitForMuseReady(page,30000);
 const turn=p.messages.filter(m=>m.role==='user').at(-1);if(!turn)throw Error('Không có tin nhắn cần theo dõi.');const marker='[brief_'+turn.id+']';
 if(!resume){p.state='sending';save(p);const packed=p.groups?await require('./movieStudio.cjs').packReferences({id:'brief_'+p.id,groups:p.groups}):null;const refs=(packed?packed.map(r=>r.tag):p.refTags).map(tag=>{const r=db.prepare('SELECT filepath FROM ref_images WHERE tag=? AND archived_at IS NULL').get(tag);if(!r||!fs.existsSync(r.filepath))throw Error('Ảnh không còn: '+tag);return {tag,file:r.filepath}});if(refs.length){await museWorker.attachImages(page,refs.map(r=>r.file));await museWorker.waitForAttachments(page,refs.map(r=>r.file))}const text=[marker,'BRIEF & CONVERSATION. Respond naturally to the brief and follow-up in this SAME conversation. Do not force a 10-second result or split into jobs. Requested duration is a target, not a verified result.',`Target duration: ${p.duration} seconds. Aspect ratio: ${p.ratio}.`,...refs.map((r,i)=>`@image${i+1} / @hinh${i+1} = attached file ${JSON.stringify(path.basename(r.file))}. Preserve the source identity, wardrobe, environment and visual style as assigned.`),packed?'ROLE SHEETS: '+packed.map((r,i)=>'Attachment '+(i+1)+' = '+r.role+' numbered contact sheet. @characterN refers to character cell N; @backgroundN to background cell N; @accessoryN to accessory cell N. Preserve these identities across episodes.').join('\n'):'','CURRENT REQUEST:',require('../videoReferences.cjs').canonicalVideoPrompt(turn.text,refs)].join('\n');await museWorker.typePrompt(page,text);await page.waitForSelector('button[data-pel-click="chat_send_message"]:not([disabled]),button[aria-label="Send"]:not([disabled])',{visible:true,timeout:15000}).then(b=>b.click());await page.waitForFunction(marker=>[...document.querySelectorAll('[data-message-item][data-message-role="user"]')].some(e=>(e.textContent||'').includes(marker)),{timeout:20000},marker);turn.delivered=true;p.url=page.url();p.state='watching';save(p);
 }else{const found=await page.evaluate(marker=>[...document.querySelectorAll('[data-message-item][data-message-role="user"]')].some(e=>(e.textContent||'').includes(marker)),marker);if(!found)throw Error('Không xác định được tin nhắn đã gửi trong phiên này. Mở MUSE để kiểm tra; app không gửi lại tự động.');p.state='watching';save(p)}
 const seen=new Set(p.results.filter(r=>r.turn===turn.id).map(r=>r.source)),deadline=Date.now()+60*60*1000;let previous='',stable=Date.now(),lastVideo=0;
 while(!ctrl.stop&&Date.now()<deadline){await new Promise(r=>setTimeout(r,4000));p.url=page.url();const data=await museWorker.resultVideosAfter(page,marker,'video',[]).catch(()=>({srcs:[],reply:''}));const reply=String(data.reply||'').slice(0,50000);if(reply!==previous){previous=reply;stable=Date.now();}if(reply){const existing=p.messages.find(m=>m.role==='assistant'&&m.turn===turn.id);if(existing)existing.text=reply;else p.messages.push({id:crypto.randomUUID(),role:'assistant',turn:turn.id,text:reply,createdAt:new Date().toISOString()});}
 for(const src of data.srcs||[]){if(seen.has(src))continue;const result=await download(page,src,p,turn.id);seen.add(src);p.results.push({...result,source:src});lastVideo=Date.now();p.state='watching';save(p)}
 const generating=await page.evaluate(()=>!!document.querySelector('button[aria-label*="Stop"],button[aria-label*="Dừng"],[data-pel-click*="stop"]')).catch(()=>true);if(!generating&&reply&&Date.now()-stable>45000){p.state=lastVideo?'completed':'awaiting';save(p);break;}if(lastVideo&&!generating&&Date.now()-lastVideo>45000){p.state='completed';save(p);break;}save(p);
 }if(ctrl.stop||Date.now()>=deadline){p.state='paused';save(p)}
 }catch(e){p.state='attention';p.error=e.message;save(p)}finally{if(ctrl.page)await ctrl.page.close().catch(()=>{});museWorker.lockedProfiles.delete(p.accountId);active.delete(id)}}
router.get('/',(req,res)=>res.json({sessions:db.prepare('SELECT payload FROM muse_brief_sessions ORDER BY updated_at DESC').all().map(r=>{const p=JSON.parse(r.payload);return {id:p.id,title:p.title,state:p.state,updatedAt:p.updatedAt}})}));
router.post('/',(req,res)=>{try{const title=String(req.body.title||'Brief mới').slice(0,160),duration=Number(req.body.duration||60),ratio=req.body.ratio||'16:9',refTags=[...new Set(req.body.refTags||[])];const groups=req.body.groups; if(groups){for(const key of ['characters','backgrounds','accessories']){if(!Array.isArray(groups[key])||groups[key].length>5||groups[key].some(x=>typeof x!=='string'))throw Error('Mỗi nhóm tham chiếu tối đa 5 ảnh')}}if(![30,50,60,90,120].includes(duration)||!['16:9','9:16','1:1'].includes(ratio)||refTags.length>5)throw Error('Thiết lập brief không hợp lệ.');res.json(save({id:crypto.randomUUID(),title,duration,ratio,refTags,groups,messages:[],results:[],state:'draft'}))}catch(e){res.status(400).json({error:e.message})}});
router.get('/:id',(req,res)=>{try{const p=read(req.params.id);res.json({...p,monitoring:active.has(p.id)})}catch(e){res.status(404).json({error:e.message})}});
router.post('/:id/message',(req,res)=>{try{const p=read(req.params.id);if(active.has(p.id)||['sending','watching','attention','paused'].includes(p.state))throw Error('Hãy tiếp tục theo dõi hoặc kiểm tra phiên MUSE trước khi gửi tiếp để tránh trùng tác vụ.');const text=String(req.body.text||'').trim();if(!text||text.length>30000)throw Error('Tin nhắn cần 1–30.000 ký tự.');require('../videoReferences.cjs').canonicalVideoPrompt(text,p.refTags);if(!p.accountId){const account=db.prepare("SELECT id FROM accounts WHERE enabled=1 AND status='online' AND jobs_running=0").all().find(a=>![...active.keys()].some(id=>read(id).accountId===a.id));if(!account)throw Error('Cần một tài khoản online đang rảnh.');p.accountId=account.id}else if(db.prepare('SELECT jobs_running FROM accounts WHERE id=?').get(p.accountId)?.jobs_running>0)throw Error('Tài khoản của phiên đang tạo video khác. Chờ hoàn tất rồi gửi.');p.error='';p.messages.push({id:crypto.randomUUID(),role:'user',text,createdAt:new Date().toISOString()});p.state='sending';save(p);monitor(p.id).catch(()=>{});res.status(202).json(p)}catch(e){res.status(400).json({error:e.message})}});
router.post('/:id/resume',(req,res)=>{try{const p=read(req.params.id);if(!p.url)throw Error('Chưa có địa chỉ phiên đã xác nhận. Mở MUSE kiểm tra tin nhắn trước khi tiếp tục.');monitor(p.id,true).catch(()=>{});res.status(202).json(read(p.id))}catch(e){res.status(400).json({error:e.message})}});
router.post('/:id/pause',(req,res)=>{const c=active.get(req.params.id);if(c)c.stop=true;res.json({message:'Dừng theo dõi trên app; tác vụ trên MUSE có thể vẫn chạy.'})});
for(const row of db.prepare('SELECT payload FROM muse_brief_sessions').all()){const p=JSON.parse(row.payload);if(['sending','watching'].includes(p.state)){p.state='paused';p.error='App đã khởi động lại. Tiếp tục theo dõi phiên, không gửi lại brief.';save(p)}}
module.exports=router;
